/**
 * report — render `results/REPORT.md` from committed files.
 *
 * Inputs are the prediction files in `predictions/` and the metrics in
 * `results/`, both committed. Nothing is re-generated by a model and nothing is
 * read from the clock, so the output is a pure function of the repo: run it
 * twice, get the same bytes, and CI can fail on a diff.
 *
 * Before rendering, the matcher is re-run over the predictions and its output is
 * compared byte-for-byte with the committed `metrics-*.json` and `matches-*.json`.
 * A mismatch means the results on disk are stale, and the report refuses rather
 * than printing numbers that no committed artifact backs. `pnpm eval` is the fix.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import { corpusHash } from "@openloop-bench/corpus";
import { buildMatchLog, readPredictionFile, scoreRun, type ScoredRun } from "../evaluate.js";
import {
  matchesPath,
  metricsPath,
  PREDICTIONS_DIR,
  REPORT_PATH,
  RESULTS_DIR,
  writeJson,
} from "../paths.js";
import { renderReport } from "../report.js";

function predictionFiles(): string[] {
  return readdirSync(PREDICTIONS_DIR)
    .filter((f) => f.endsWith(".json"))
    .sort()
    .map((f) => join(PREDICTIONS_DIR, f));
}

/** Committed artifact must exist and match what this run recomputes. */
function checkArtifact(path: string, expected: string): string | null {
  if (!existsSync(path)) return `${basename(path)} is missing`;
  return readFileSync(path, "utf-8") === expected ? null : `${basename(path)} is stale`;
}

function main(): void {
  const files = predictionFiles();
  if (files.length === 0) {
    console.log(`report: no prediction files in ${PREDICTIONS_DIR}`);
    process.exitCode = 1;
    return;
  }

  const runs: ScoredRun[] = [];
  const problems: string[] = [];

  for (const path of files) {
    const file = readPredictionFile(path);
    const scored = scoreRun(file);
    runs.push(scored);

    const { config, split } = file.meta;
    const stale = [
      checkArtifact(metricsPath(config, split), writeJson(scored.run)),
      checkArtifact(matchesPath(config, split), writeJson(buildMatchLog(scored))),
    ].filter((problem): problem is string => problem !== null);
    problems.push(...stale);
  }

  if (problems.length > 0) {
    console.log("report refuses to render against stale results:");
    for (const problem of problems) console.log(`  ${problem}`);
    console.log("");
    console.log("Run `pnpm eval` first — REPORT.md must not state a number no committed artifact backs.");
    process.exitCode = 1;
    return;
  }

  mkdirSync(RESULTS_DIR, { recursive: true });
  const markdown = renderReport({ runs, corpusHash: corpusHash() });
  writeFileSync(REPORT_PATH, markdown);

  console.log(`openloop-bench report — ${runs.length} config(s), corpus ${corpusHash()}`);
  console.log("");
  for (const run of runs) {
    console.log(`  ${run.run.meta.config.padEnd(16)} ${run.run.meta.model_id}  (${run.run.meta.generated_at})`);
  }
  console.log("");
  console.log(`Written ${REPORT_PATH} (${markdown.split("\n").length} lines).`);
}

main();
